// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 balance0, uint256 amount, address receiver) public {
        vm.assume(receiver != address(this));
        balance0 = bound(balance0, 1 wei, 1000 ether);
        amount = bound(amount, 0, balance0 - 1);

        vm.deal(address(c), balance0);
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        assertEq(address(c).balance, balance0 - amount);
    }
}
